arguments.new_string:
        if errs:
            # TODO: due to the usage of basic path (not a Path
            # object), the format can be a bit inconsistent here
            # (e.g., 'a.b' and ['a', 'b'])
            raise CheckError(errs, self, scope[Path])
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        args = [repr(self.spec)]
        if self.default is not RAISE:
            args.append('default=%r' % (self.default,))
        if self.types:
            args.append('types=%r' % (list(self.types),))
        if self.vals:
            args.append('one_of=%r' % (list(self.vals),))
        if self.instance_of:
            args.append('instance_of=%r' % (list(self.instance_of),))
        if self.validators:
            args.append('validate=%r' % (list(self.validators),))
        return '%s(%s)' % (cn, ', '.join(args))


